#include "capi.h"
*/
import "C"
import (
  "sync"
  "unsafe"
)

var (
  mu       sync.Mutex
  cbStore  = map[uintptr]func(int){}
  nextKey  uintptr = 1
)

//export goCallback
func goCallback(event C.int, ctx unsafe.Pointer) {
  mu.Lock()
  if f, ok := cbStore[uintptr(ctx)]; ok {
    f(int(event))
  }
  mu.Unlock()
